246	\section{The Jacobian and its structure}
247	
248	\begin{definition}[Jacobian]
249	  \label{def:Jacobian}
250	  \uses{def:genus, def:JacobianWitness, def:jacobianWitness}
251	  \lean{AlgebraicGeometry.Jacobian}
252	  The \emph{Jacobian} \(\Jac(C)\) is the underlying \(k\)-scheme of the
253	  chosen Jacobian witness.  Equivalently, \(\Jac(C)=\Pic^0_{C/k}\) up to the
254	  unique isomorphism of Albanese objects.
255	\end{definition}
256	
257	\begin{theorem}[Group structure]
258	  \label{thm:Jacobian_grpObj}
259	  \uses{def:Jacobian, def:jacobianWitness}
260	  \lean{AlgebraicGeometry.Jacobian.instGrpObj}
261	  The Jacobian is a group scheme over \(k\).
262	\end{theorem}
263	
264	\begin{proof}
265	  This is the group structure carried by the chosen Jacobian witness.
266	\end{proof}
267	
268	\begin{theorem}[Dimension and smoothness]
269	  \label{thm:Jacobian_smooth_genus}
270	  \uses{def:Jacobian, def:genus, def:jacobianWitness}
271	  \lean{AlgebraicGeometry.Jacobian.smoothOfRelativeDimension_genus}
272	  The structural morphism \(\Jac(C)\to\Spec k\) is smooth of relative
273	  dimension \(g(C)\).
274	\end{theorem}
275	
276	\begin{proof}
277	  This is the dimension assertion carried by the chosen Jacobian witness.
278	\end{proof}
279	
280	\begin{theorem}[Properness]
281	  \label{thm:Jacobian_proper}
282	  \uses{def:Jacobian, def:jacobianWitness}
283	  \lean{AlgebraicGeometry.Jacobian.instIsProper}
284	  The structural morphism \(\Jac(C)\to\Spec k\) is proper.
285	\end{theorem}
286	
287	\begin{proof}
288	  This is the properness assertion carried by the chosen Jacobian witness.
289	\end{proof}
290	
291	\begin{theorem}[Geometric irreducibility]
292	  \label{thm:Jacobian_geomIrred}
293	  \uses{def:Jacobian, def:jacobianWitness}
294	  \lean{AlgebraicGeometry.Jacobian.instGeometricallyIrreducible}
295	  The structural morphism \(\Jac(C)\to\Spec k\) is geometrically irreducible.
296	\end{theorem}
297	
298	\begin{proof}
299	  This is the geometric-irreducibility assertion carried by the chosen
300	  Jacobian witness.
301	\end{proof}
302	
303	\begin{remark}
304	  If \(g(C)=0\), then \(\Jac(C)=\Spec k\).  If \(g(C)=1\) and \(C(k)\) is
305	  nonempty, the choice of a rational point identifies \(C\) with its
306	  Jacobian.  For \(g(C)\geq2\), the Jacobian has dimension \(g(C)\), whereas
307	  \(C\) has dimension one.
308	\end{remark}
