310	\section{The Albanese property of \(\Pic^0\)}
311	\label{sec:Jacobian_routeA4_albaneseUP}
312	
313	\begin{theorem}
314	[Albanese universal property of \(\Pic^0_{C/k}\)]
315	  \label{thm:albanese_universal_property_northstar}
316	  \uses{lem:abel_jacobi_morphism, lem:symmetric_product_av_map,
317	    lem:symmetric_product_to_jacobian, lem:descent_through_birational_sigma,
318	    lem:albanese_eq_iff_symmetricPower_eq, thm:rational_map_to_av_extends,
319	    thm:rigidity_lemma, lem:av_regular_map_is_hom,
320	    lem:hom_additivity_over_product}
321	  Fix \(P\in C(k)\), put \(J=\Pic^0_{C/k}\), and let
322	  \(f^P(Q)=[\mathcal O_C(Q-P)]\).  For every pointed morphism
323	  \(\varphi\colon C\to A\) to an abelian variety there is a unique
324	  group-scheme homomorphism \(\psi\colon J\to A\) such that
325	  \(\varphi=f^P\circ\psi\).
326	\end{theorem}
327	
328	\begin{proof}
329	  For \(g=g(C)>0\), the morphism
330	  \[
331	    (Q_1,\ldots,Q_g)\longmapsto
332	      \varphi(Q_1)+\cdots+\varphi(Q_g)
333	  \]
334	  is symmetric and therefore descends to \(C^{(g)}\).  The Abel map
335	  \(C^{(g)}\to J\) is birational onto \(J\), so this descent defines a
336	  rational map \(J\dashrightarrow A\).  A rational map from a nonsingular
337	  variety to an abelian variety extends uniquely to a regular morphism;
338	  denote the extension by \(\psi\).  By construction
339	  \(\varphi=f^P\circ\psi\), and \(\psi(0)=0\), so rigidity makes \(\psi\) a
340	  homomorphism.  If \(\psi'\) is another such homomorphism, then \(\psi\) and
341	  \(\psi'\) agree on the sum of \(g\) copies of \(f^P(C)\), which is all of
342	  \(J\); hence \(\psi=\psi'\).  When \(g=0\), \(J=\Spec k\) and the result
343	  follows from rigidity.
344	\end{proof}
